const OPPONENT = {
  best: ["{opp} found the best move: {move}.", "Strong reply. {move} is the engine’s choice.", "{move} is accurate. Stay alert."],
  excellent: ["{opp} played {move}, an excellent move.", "{move} is a strong reply.", "A good answer: {move}."],
  good: ["{opp} played {move}, a solid move.", "{move} is a reasonable reply.", "{move}. A sensible choice."],
  inaccuracy: ["{opp} played {move}, a small inaccuracy.", "{move} is slightly imprecise. Look for a chance.", "{move} gives you a little room."],
  mistake: ["{opp} made a mistake with {move}. Look for it!", "{move} is a mistake. There’s an opportunity now.", "{move} lets you in. Find the best reply."],
  blunder: ["{opp} blundered with {move}! Punish it.", "{move} is a blunder. Look for the win.", "Big chance: {move} was a blunder."],
};
const PIECES = { K: "king", Q: "queen", R: "rook", B: "bishop", N: "knight" };

function hash(text) {
  let value = 2166136261;
  for (const char of text) value = Math.imul(value ^ char.charCodeAt(0), 16777619) >>> 0;
  return value;
}
function fill(line, san) {
  const piece = PIECES[san?.[0]] || (san?.startsWith("O-O") ? "king" : "pawn");
  return line.replaceAll("{move}", san || "that").replaceAll("{piece}", piece);
}
// Avoid saying the same line twice in a row for the same commentator.
const recent = new Map();
function pick(options, seed, key) {
  let index = hash(seed) % options.length;
  const previous = recent.get(key);
  if (previous && previous.seed !== seed && previous.index === index) index = (index + 1) % options.length;
  if (!previous || previous.seed !== seed) recent.set(key, { seed, index });
  else index = previous.index;
  return options[index];
}

/** A reaction line that stays the same for the same move and varies between moves. */
export function reactionLine(gradeKey, seed, coachId = "nova", san) {
  const voice = LINES[coachId] || LINES.nova;
  const options = voice[gradeKey] || voice.good;
  const move = san || /([KQRBN]?[a-h]?[1-8]?x?[a-h][1-8](?:=[QRBN])?|O-O(?:-O)?)[+#]?$/.exec(seed)?.[0];
  return fill(pick(options, seed, coachId), move);
}

export function opponentLine(gradeKey, san) {
  const options = OPPONENT[gradeKey] || OPPONENT.good;
  return fill(pick(options, "opp" + san + gradeKey, "opponent"), san).replaceAll("{opp}", "Your opponent");
}
